#include <bits/stdc++.h>
using namespace std;const int N=85;int id[10][10],u[145],v[145],f[N];char s[10][10];int g(int x){return f[x]==x?x:f[x]=g(f[x]);}int main(){ios::sync_with_stdio(0);cin.tie(0);int n,m,k=0,e=0;cin>>n>>m;for(int i=0;i<n;i++){cin>>s[i];for(int j=0;j<m;j++)if(s[i][j]=='.')id[i][j]=k++;else id[i][j]=-1;}for(int i=0;i<n;i++)for(int j=0;j<m;j++)if(id[i][j]>=0){if(i+1<n&&id[i+1][j]>=0)u[e]=id[i][j],v[e++]=id[i+1][j];if(j+1<m&&id[i][j+1]>=0)u[e]=id[i][j],v[e++]=id[i][j+1];}long long r=0;for(int q=0;q<(1<<e);q++)if(__builtin_popcount(q)==k-1){for(int i=0;i<k;i++)f[i]=i;bool z=1;for(int i=0;i<e;i++)if(q>>i&1){int x=g(u[i]),y=g(v[i]);if(x==y){z=0;break;}f[x]=y;}r+=z;}cout<<r%1000000000<<'\n';}
